#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# 本向导只做一件事：把 gh 登进 github.com，并证明这把凭据真能用。
# 装 gh / 建标签 / CI secrets 都不在这里 —— 那些在 scripts/setup-github-cli.sh。
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=4

banner "gh 登录向导 · todo-kanban"

# _ghbin 定位 gh：安装器改的是注册表 PATH，已开着的终端读不到新值，所以 PATH 找不到时
# 回退 MSI 默认目录（Git Bash 的 /c/ 写法）。与 setup-github-cli.sh 保持同一套逻辑。
GH_BIN=""
_ghbin() {
  if command -v gh >/dev/null 2>&1; then GH_BIN="gh"
  elif [ -x "/c/Program Files/GitHub CLI/gh.exe" ]; then GH_BIN="/c/Program Files/GitHub CLI/gh.exe"
  elif [ -x "/c/Program Files (x86)/GitHub CLI/gh.exe" ]; then GH_BIN="/c/Program Files (x86)/GitHub CLI/gh.exe"
  else GH_BIN=""; return 1; fi
  return 0
}

# _probe URL [CURL_EXTRA...]：只打一个 HTTP 状态码，且清空代理变量（理由见阶段 1）。
# 空输出补 000 时不要再 || printf '000'：curl 连不上时 -w 自己就输出 000，补第二次会拼成
# 000000，于是「完全没反应」被读成「有响应」—— 上一版栽在这里，实测复现过。
_probe() {
  local url="$1" c=""
  shift
  c=$(HTTPS_PROXY= HTTP_PROXY= ALL_PROXY= curl -sS -m 12 -o /dev/null -w '%{http_code}' "$@" "$url" 2>/dev/null) || true
  if [ -z "$c" ]; then c=000; fi
  printf '%s' "$c"
}

REPO_ROOT="$(cd "$(dirname "$0")/.." && pwd)"
PROXY_URL="http://127.0.0.1:7890"
DEVICE_URL="https://github.com/login/device"
INTRANET_HOSTS="git.novogene.com,172.17.165.229,.novogene.com,localhost,127.0.0.1"

# ──────────────────────────────────────────────────────────────────────────
# 阶段 1：把三种「不通」分开判 —— 修法完全不同，混判就会得出错结论
# ──────────────────────────────────────────────────────────────────────────
stage "通道自检：三种不通分开判"
say "这一步只探路、不写任何东西，而且刻意在清空代理变量的环境里探。"
note "为什么清空：2026-10-22 本机实测 api.github.com 直连 200，而 127.0.0.1:7890 对 GitHub 两"
note "条域名全是 curl (35) schannel 握手失败。所以「先配代理再登录」这个直觉在当前网络上是帮"
note "倒忙 —— setup-github-cli.sh 阶段 2 默认 export HTTPS_PROXY，本向导不沿用那个方向。"
_api_direct="$(_probe https://api.github.com/meta)"
_api_via="$(_probe https://api.github.com/meta -x "$PROXY_URL")"
_root_rev="$(_probe https://github.com)"
_root_norev="$(_probe https://github.com --ssl-no-revoke)"
say "  api.github.com   直连=$_api_direct   经代理=$_api_via"
say "  github.com 根页  默认=$_root_rev   --ssl-no-revoke=$_root_norev"

api_ok=0; proxy_only=0
if [ "$_api_direct" != "000" ]; then api_ok=1; fi
if [ "$api_ok" = 0 ] && [ "$_api_via" != "000" ]; then api_ok=1; proxy_only=1; fi

# 根页默认 000 而 --ssl-no-revoke 非 000 ⇒ 是 Windows Schannel 的证书吊销列表检查离线
# （CRYPT_E_REVOCATION_OFFLINE），不是域名不通。浏览器与 gh 的 Go TLS 栈都不做这个检查，
# 所以绝不能拿 curl 的 000 去推断「浏览器也打不开」—— 上一版正是这样误判了设备码的可行性。
if [ "$_root_rev" = "000" ] && [ "$_root_norev" != "000" ]; then
  note "判读：根页的 000 是吊销检查离线造成的假阴性（去掉该检查就通），不是封禁。"
fi

if [ "$api_ok" = 0 ]; then
  say "✗ api.github.com 直连与经代理都不通：gh 无论走哪条分支都登不上，先修网络。"
  warn "  反复的 curl (35) schannel handshake 失败通常是代理节点出站 TLS 坏了，不是 GitHub 挂了。"
  finish
  exit 0
fi
if [ "$proxy_only" = 1 ]; then
  export HTTPS_PROXY="$PROXY_URL" HTTP_PROXY="$PROXY_URL" NO_PROXY="$INTRANET_HOSTS"
  say "⚠ 只有走代理才通 → 已在本向导进程内导出 HTTPS_PROXY（不 setx，只在本次登录期间生效）。"
  note "  NO_PROXY 带上内网：本仓库的 Git 报告功能经系统 curl 访问 GitLab（ADR-016），内网地址"
  note "  一旦被 Clash 接走那条就断了 —— 这是刻意配 NO_PROXY 的原因。"
else
  say "✓ gh 的 API 通道正常（直连），后续 gh 命令都不带代理。"
fi
pause "看完结果按 Enter 继续"

# ──────────────────────────────────────────────────────────────────────────
# 阶段 2：遥测闸门（本机约定：第三方工具默认关上报，并告知用户）
# ──────────────────────────────────────────────────────────────────────────
stage "遥测闸门"
say "gh 把开关文档化了（来源：gh help environment）：GH_TELEMETRY=false 关上报，且优先级"
note "高于 DO_NOT_TRACK；DO_NOT_TRACK=true 是通用约定。配置项那条偏软，环境变量那条更硬。"
if _ghbin; then
  if "$GH_BIN" config set telemetry disabled 2>/dev/null; then
    say "✓ gh config set telemetry disabled（配置项，重复执行无害）"
  else
    warn "配置写入失败：稍后手动跑 gh config set telemetry disabled"
    SKIPPED+=("gh 遥测未关：手动跑 gh config set telemetry disabled")
  fi
  _cfg="$("$GH_BIN" config list 2>/dev/null)" || true
  if [ -n "$_cfg" ]; then
    note "当前 gh 配置（gh config list）："
    printf '%s' "$_cfg" | sed 's/^/      /'
  fi
  _reg="$(reg query 'HKCU\Environment' /v GH_TELEMETRY 2>/dev/null | grep -o 'false' || true)"
  if [ -n "$_reg" ]; then
    say "✓ 用户环境变量里已有 GH_TELEMETRY=false（比配置项优先，新终端也生效）"
  else
    note "本会话 GH_TELEMETRY=${GH_TELEMETRY:-未设置}（setx 只对**新开的**终端生效）"
    if confirm "补写 GH_TELEMETRY=false 到用户环境变量？"; then
      if setx GH_TELEMETRY false >/dev/null 2>&1; then
        say "✓ 已写入（撤销：reg delete 'HKCU\Environment' /v GH_TELEMETRY /f）"
      else
        warn "setx 失败，可在「系统属性 → 环境变量」里手动加 GH_TELEMETRY=false"
      fi
    else
      SKIPPED+=("GH_TELEMETRY 未持久化：只关了 gh 自己的配置项")
    fi
  fi
else
  SKIPPED+=("gh 不可用：无法关遥测也无法登录，先跑 scripts/setup-github-cli.sh 安装")
  warn "PATH 与 MSI 默认目录里都没找到 gh。"
fi
pause "按 Enter 继续"

# ──────────────────────────────────────────────────────────────────────────
# 阶段 3：登录。设备码可行性现场探，不照抄任何历史结论
# ──────────────────────────────────────────────────────────────────────────
stage "登录 github.com"
skip_login=0
if ! _ghbin; then
  warn "gh 不可用，跳过登录（阶段 2 已记录）。"
  skip_login=1
elif "$GH_BIN" auth status >/dev/null 2>&1; then
  say "当前已是登录态："
  "$GH_BIN" auth status 2>&1 | sed 's/^/    /' || true
  if confirm "注销并重登？选 N 直接进验收。"; then
    "$GH_BIN" auth logout --hostname github.com >/dev/null 2>&1 || true
    say "已注销，下面重新登录。"
  else
    skip_login=1
    say "保留现有凭据。"
  fi
fi

if [ "$skip_login" = 0 ]; then
  _dev="$(_probe "$DEVICE_URL" --ssl-no-revoke)"
  say "设备码授权页探测：$DEVICE_URL → $_dev"
  device_ok=0
  if [ "$_dev" != "000" ]; then device_ok=1; fi
  if [ "$device_ok" = 1 ]; then
    say "✓ 授权页可达 → 浏览器设备码可用（浏览器走系统代理，与 curl 那条是两回事）。"
  else
    warn "⚠ 授权页不可达：连 --ssl-no-revoke 都超时 ⇒ 换 TLS 栈也救不了，是真的封在路径上"
    warn "  （根页能开而 /login/device 不行，是路径级区别对待）⇒ 设备码这条路现在走不通。"
    note "  要修的是代理客户端：托盘打开 Clash Verge，在「代理 / Proxies」换一个能连通海外的节点。"
    note "  界面中文用词以你本机版本为准，别照我猜的按钮名硬找。"
  fi
  say "三条分支："
  say "  A) 复用 git 凭据助手里的 PAT —— 只需 api.github.com 通，不碰浏览器"
  note "     （就是 CLAUDE.md 里 build.sh 写明的凭据链：GITHUB_TOKEN → gh auth token → git credential）"
  say "  B) 浏览器设备码 gh auth login --web"
  say "  C) 在别的设备上新建经典 PAT，回来隐藏粘贴"
  if [ "$device_ok" = 1 ]; then
    ask LOGIN_MODE "走哪条 [A/B/C]（回车 B）："
    LOGIN_MODE="${LOGIN_MODE:-B}"
  else
    ask LOGIN_MODE "走哪条 [A/B/C]（回车 A）："
    LOGIN_MODE="${LOGIN_MODE:-A}"
  fi
  case "$LOGIN_MODE" in
    [Bb]*)
      step "将执行：gh auth login --hostname github.com --git-protocol https --web --skip-ssh-key --scopes repo,read:org,workflow"
      note "交互式界面归你操作：GitHub.com → HTTPS → 是否用 GitHub 凭据认证 Git 选 Yes → Login with a web browser。"
      note "终端打印形如 XXXX-XXXX 的一次性码 → 浏览器打开授权页粘码 → Authorize。"
      note "--skip-ssh-key 是不把 SSH 生成/上传卷进来（本仓库走 HTTPS）；--clipboard 会覆盖你的"
      note "剪贴板（默认只打印代码不复制），需要时自己加 -c。"
      open_url "$DEVICE_URL"
      pause "准备好后回车启动登录（之后的界面归你）"
      "$GH_BIN" auth login --hostname github.com --git-protocol https --web --skip-ssh-key --scopes repo,read:org,workflow || warn "设备码没走完：重跑本向导改走 A/C，或手动执行上面那条命令"
      ;;
    [Cc]*)
      step "在另一台能上网的设备（手机热点也行）打开经典 PAT 创建页"
      open_url "https://github.com/settings/tokens/new?scopes=repo,read:org,gist,workflow&description=todo-kanban%20(gh%20CLI%20local)"
      note "gh 手册要求经典 PAT 的最小作用域是 repo / read:org / gist；workflow 用于 push 工作流文件。"
      note "过期建议 90 天内。URL 已预填 scopes，页面没自动勾就手动勾。"
      ask_secret GH_PAT "粘贴 token（输入不回显）："
      if [ -n "${GH_PAT:-}" ]; then
        if printf '%s' "$GH_PAT" | "$GH_BIN" auth login --with-token; then
          say "✓ 已用 PAT 登录"
        else
          warn "失败：token 过期或作用域不足"
          SKIPPED+=("gh 拒绝了这把 PAT")
        fi
        unset GH_PAT
      else
        warn "没粘贴内容，跳过。"
        SKIPPED+=("未登录：没有可用 PAT")
      fi
      ;;
    *)
      step "从 git 凭据助手取出**已存在**的 github.com 凭据，经 stdin 交给 gh"
      note "安全边界：内容不回显、不落文件、不进命令行参数（命令行参数会进进程列表与 shell 历史）、用完立即 unset。"
      note "GIT_TERMINAL_PROMPT=0 与 -c credential.interactive=false 是为了绝不弹 GUI 询问框。"
      _cred="$({ echo 'protocol=https'; echo 'host=github.com'; echo; } | GIT_TERMINAL_PROMPT=0 git -c credential.interactive=false credential fill 2>/dev/null)" || true
      _user="$(printf '%s' "$_cred" | sed -n 's/^username=//p' | head -n1)"
      _tok="$(printf '%s' "$_cred" | sed -n 's/^password=//p' | head -n1)"
      unset _cred
      if [ -z "$_tok" ]; then
        warn "git 凭据助手里没有 github.com 的凭据（或系统钥匙串拒绝访问）。"
        say "改走分支 C：在别的设备上新建经典 PAT 再粘进来。"
        SKIPPED+=("git 凭据里没有 github.com：需手动建 PAT")
      else
        say "  username = ${_user:-（凭据里未写用户名）}   password 长度 = ${#_tok} 字符（内容刻意不显示）"
        note "这是本次向导唯一的写操作：gh 会把这把凭据存进 Windows 凭据管理器。"
        if confirm "同意把这把 git 里已存的 PAT 交给 gh 保存？"; then
          if printf '%s' "$_tok" | "$GH_BIN" auth login --with-token; then
            say "✓ gh 已接管这把凭据"
          else
            warn "gh 拒绝了它：可能过期或作用域不足"
            SKIPPED+=("gh 拒绝了 git 里的 PAT：需另建一把")
          fi
        else
          warn "你拒绝了，未写入任何凭据。"
          SKIPPED+=("未登录：你选择不复用 git 凭据")
        fi
      fi
      unset _tok _user
      ;;
  esac
fi
pause "按 Enter 进验收"

# ──────────────────────────────────────────────────────────────────────────
# 阶段 4：确认 —— 不只问「存了没有」，要证明这把凭据真能用
# ──────────────────────────────────────────────────────────────────────────
stage "确认已登录"
if _ghbin; then
  step "gh auth status"
  if "$GH_BIN" auth status 2>&1 | sed 's/^/    /'; then
    :
  else
    warn "gh auth status 退出码非 0：还没真正登录成功"
    SKIPPED+=("gh 未登录：完成后跑 gh auth login")
  fi
  note "它只列主机 / 账号 / 作用域，默认不显示 token —— 这是设计，不是你漏看了。"

  step "gh api /user：只信 auth status 不够，得证明这把凭据真能用"
  _login="$("$GH_BIN" api /user --jq .login 2>/dev/null)" || true
  if [ -n "$_login" ]; then
    say "    ✓ 凭据有效，身份 = $_login"
  else
    warn "    ✗ 读不到身份：token 过期 / 作用域不足（经典 PAT 至少要 repo、read:org、gist）/ 通道又坏了"
    SKIPPED+=("gh 凭据读不到 /user：需换一把作用域足够的 PAT")
  fi
  unset _login

  step "gh repo view：issue-tracker.md 的 gh:repoAccess 口径，全只读"
  if (cd "$REPO_ROOT" && "$GH_BIN" repo view --json nameWithOwner,defaultBranchRef 2>&1 | sed 's/^/    /'); then
    say "    ✓ 本仓库可读，wayfinder / deck 那套技能可以直接开工"
  else
    warn "    ✗ 读不到本仓库：未登录 / 无权限 / 通道不通"
    SKIPPED+=("gh:repoAccess 红")
  fi

  note "git 侧不受本向导影响：--with-token 分支不会改 git 的 credential.helper 或 url 配置，"
  note "gh 与 git 各存各的凭据（所以 bash build.sh 的凭据链照旧可用）。"
else
  warn "gh 仍不可用，验收做不了。"
fi
note "想改走浏览器设备码：先在 Clash Verge 换节点，再跑这一条复测（非 000 才算通）："
note "  curl -sS -m 12 --ssl-no-revoke -o /dev/null -w '%{http_code}' https://github.com/login/device"

finish
